custom_css:
.candidate-checker-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

/* Header Section */
.checker-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: #2c3e50;
  margin-bottom: 1rem;
}

.section-description {
  font-size: 1.1rem;
  color: #7f8c8d;
  line-height: 1.6;
}

.candidate-search-form {
  background: #ffffff;
  padding: 2.5rem;
  border-radius: 12px;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
  margin-bottom: 3rem;
  border: 1px solid #e8ecef;
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-weight: 600;
  color: #2c3e50;
  margin-bottom: 0.5rem;
  font-size: 1rem;
}

.form-group input {
  width: 100%;
  padding: 0.875rem 1rem;
  border: 2px solid #e8ecef;
  border-radius: 8px;
  font-size: 1rem;
  transition: all 0.3s ease;
  background: #ffffff;
}

.form-group input:focus {
  outline: none;
  border-color: #3498db;
  box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.1);
}

.form-actions {
  text-align: center;
  margin-top: 2rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.3s ease;
  gap: 0.5rem;
}

.btn-primary {
  background: linear-gradient(135deg, #3498db, #2980b9);
  color: white;
}

.btn-primary:hover {
  background: linear-gradient(135deg, #2980b9, #1f6391);
  transform: translateY(-2px);
  box-shadow: 0 8px 15px rgba(52, 152, 219, 0.3);
}

.btn-outline {
  background: transparent;
  color: #3498db;
  border: 2px solid #3498db;
}

.btn-outline:hover {
  background: #3498db;
  color: white;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

/* Loading Spinner */
.btn-loading .fa-spin {
  animation: fa-spin 1s infinite linear;
}

@keyframes fa-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.alert {
  padding: 1rem 1.5rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.alert-success {
  background: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
}

.alert-error {
  background: #f8d7da;
  color: #721c24;
  border: 1px solid #f5c6cb;
}

.candidate-card {
  background: #ffffff;
  border-radius: 12px;
  padding: 2rem;
  margin-bottom: 2rem;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
  border: 1px solid #e8ecef;
}

.candidate-info {
  display: flex;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid #e8ecef;
}

.candidate-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  overflow: hidden;
  margin-right: 1.5rem;
  position: relative;
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.avatar-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #3498db, #2980b9);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 2rem;
}

.candidate-details h4 {
  margin: 0 0 0.5rem 0;
  color: #2c3e50;
  font-size: 1.25rem;
  font-weight: 600;
}

.candidate-details p {
  margin: 0.25rem 0;
  color: #7f8c8d;
}

.applications-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: #2c3e50;
  margin-bottom: 1rem;
}

.application-item {
  background: #f8f9fa;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1rem;
  border-left: 4px solid #3498db;
}

.application-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.job-title {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
  color: #2c3e50;
}

.application-status {
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.875rem;
  font-weight: 500;
  background: #e3f2fd;
  color: #1976d2;
}

.application-details {
  margin-bottom: 1rem;
}

.detail-row {
  display: flex;
  margin-bottom: 0.5rem;
}

.detail-row .label {
  font-weight: 600;
  color: #2c3e50;
  width: 140px;
  flex-shrink: 0;
}

.detail-row .value {
  color: #7f8c8d;
}

/* Stage Timeline */
.stages-timeline {
  position: relative;
  margin-top: 1rem;
}

.stage-item {
  display: flex;
  align-items: center;
  margin-bottom: 0.75rem;
  padding-left: 2rem;
  position: relative;
}

.stage-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #3498db;
}

.stage-item.completed::before {
  background: #27ae60;
}

.stage-item.current::before {
  background: #f39c12;
}

.jobs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 1.5rem;
  margin-top: 1.5rem;
}

.job-card {
  background: #ffffff;
  border-radius: 8px;
  padding: 1.5rem;
  border: 1px solid #e8ecef;
  transition: all 0.3s ease;
}

.job-card:hover {
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}

.job-header h4 {
  margin: 0 0 1rem 0;
  color: #2c3e50;
  font-size: 1.1rem;
}

.job-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.job-meta span {
  background: #e3f2fd;
  color: #1976d2;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-size: 0.875rem;
}

.job-salary,
.job-deadline {
  margin-bottom: 0.5rem;
  color: #7f8c8d;
}

/* ===== ONBOARDING STYLES - PHẦN MỚI ===== */

/* Container và transitions */
#container {
  transition: opacity 0.3s ease;
}

/* Onboarding Summary */
#onboarding-summary {
  background: linear-gradient(135deg, #f8f9fa, #ffffff);
  border-left: 4px solid #28a745;
}

/* Progress Circle */
#progress-circle {
  transition: stroke-dashoffset 0.6s ease-in-out;
  filter: drop-shadow(0 2px 4px rgba(40, 167, 69, 0.2));
}

#progress-percentage {
  font-weight: 700;
  color: #2c3e50;
}

/* Onboarding Steps */
.onboarding-step {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.onboarding-step:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
}

.onboarding-step::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(180deg, #3498db, #2980b9);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.onboarding-step:hover::before {
  opacity: 1;
}

/* Step Icon */
.step-icon {
  transition: all 0.3s ease;
  position: relative;
  z-index: 2;
}

.step-icon::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: all 0.3s ease;
}

.onboarding-step:hover .step-icon::after {
  width: 100%;
  height: 100%;
}

/* Step Status Badges */
.step-status {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.step-status::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
  transition: left 0.6s ease;
}

.onboarding-step:hover .step-status::before {
  left: 100%;
}

/* File Upload Styles */
.upload-area {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.upload-area::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.05), rgba(37, 99, 235, 0.05));
  opacity: 0;
  transition: opacity 0.3s ease;
}

.upload-area:hover::before {
  opacity: 1;
}

.upload-area:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(59, 130, 246, 0.15);
  border-color: #3b82f6;
}

/* Drag states */
.upload-area.drag-over {
  border-color: #3b82f6 !important;
  background-color: #dbeafe !important;
  transform: scale(1.02);
}

.upload-area.drag-over .upload-icon i {
  transform: scale(1.1);
  color: #3b82f6;
}

/* Browse button */
.browse-btn {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.browse-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.6s ease;
}

.browse-btn:hover::before {
  left: 100%;
}

.browse-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 15px rgba(37, 99, 235, 0.3);
}

/* File Preview Area */
.file-preview-area {
  animation: slideInUp 0.4s ease;
  background: linear-gradient(135deg, #ebf8ff, #f0f9ff);
  border: 2px solid #3b82f6;
}

@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* File icon animations */
.file-icon i {
  transition: all 0.3s ease;
}

.file-preview-area:hover .file-icon i {
  transform: scale(1.1) rotate(5deg);
}

/* Progress Bar */
.upload-progress {
  animation: fadeIn 0.3s ease;
}

.upload-progress-bar {
  transition: width 0.3s ease;
  background: linear-gradient(90deg, #3b82f6, #1d4ed8);
  position: relative;
  overflow: hidden;
}

.upload-progress-bar::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
  animation: progressShine 1.5s infinite;
}

@keyframes progressShine {
  0% { left: -100%; }
  100% { left: 100%; }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Uploaded File Success */
.uploaded-file-info {
  animation: successPulse 0.6s ease;
  background: linear-gradient(135deg, #dcfce7, #f0fdf4);
  border: 2px solid #22c55e;
}

@keyframes successPulse {
  0% {
    opacity: 0;
    transform: scale(0.9);
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

.uploaded-icon i {
  animation: checkBounce 0.6s ease;
}

@keyframes checkBounce {
  0%, 20%, 60%, 100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-10px);
  }
  80% {
    transform: translateY(-5px);
  }
}

/* Action Buttons */
.mark-complete-btn {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.mark-complete-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.6s ease;
}

.mark-complete-btn:hover::before {
  left: 100%;
}

.mark-complete-btn:hover {
  background: linear-gradient(135deg, #16a34a, #15803d);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(34, 197, 94, 0.3);
}

/* Upload and Remove buttons */
.upload-btn {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  transition: all 0.3s ease;
}

.upload-btn:hover {
  background: linear-gradient(135deg, #16a34a, #15803d);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(34, 197, 94, 0.3);
}

.remove-file-btn {
  transition: all 0.3s ease;
}

.remove-file-btn:hover {
  background: #fecaca;
  transform: scale(1.1);
}

/* HR Approval and Completed Info */
.hr-approval-info {
  animation: pulseYellow 2s infinite;
}

@keyframes pulseYellow {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.4);
  }
  50% {
    box-shadow: 0 0 0 10px rgba(245, 158, 11, 0);
  }
}

.step-completed-info {
  animation: fadeInScale 0.5s ease;
}

@keyframes fadeInScale {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Loading animations */
.fa-spinner {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Jobs Section */
#jobs-section {
  background: linear-gradient(135deg, #f8fafc, #ffffff);
  border-radius: 12px;
  padding: 2rem;
  margin-top: 2rem;
}

/* Responsive Design */
@media (max-width: 768px) {
  .candidate-checker-container {
    padding: 1rem;
  }

  .section-title {
    font-size: 2rem;
  }

  .candidate-search-form {
    padding: 1.5rem;
  }

  .candidate-info {
    flex-direction: column;
    text-align: center;
  }

  .candidate-avatar {
    margin-right: 0;
    margin-bottom: 1rem;
  }

  .jobs-grid {
    grid-template-columns: 1fr;
  }

  .detail-row {
    flex-direction: column;
  }

  .detail-row .label {
    width: auto;
    margin-bottom: 0.25rem;
  }

  /* Onboarding responsive */
  .onboarding-step {
    padding: 1rem;
  }

  .onboarding-step .flex {
    flex-direction: column;
    align-items: flex-start;
    gap: 1rem;
  }

  .step-icon {
    align-self: center;
  }

  .upload-area {
    padding: 1.5rem;
  }

  .upload-area .upload-text {
    font-size: 0.9rem;
  }

  .file-preview-area .flex {
    flex-direction: column;
    gap: 1rem;
  }

  .file-actions {
    justify-content: center;
    width: 100%;
  }

  .file-actions button {
    flex: 1;
    max-width: 150px;
  }

  /* Progress circle responsive */
  #onboarding-summary .flex {
    flex-direction: column;
    text-align: center;
    gap: 1rem;
  }

  #onboarding-summary .w-32 {
    align-self: center;
  }
}

@media (max-width: 480px) {
  .upload-area {
    padding: 1rem;
  }

  .browse-btn {
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
  }

  .upload-icon i {
    font-size: 2.5rem;
  }

  .step-actions {
    flex-direction: column;
    gap: 0.5rem;
  }

  .step-actions button,
  .step-actions div {
    width: 100%;
    justify-content: center;
  }
}

/* Dark mode support (optional) */
@media (prefers-color-scheme: dark) {
  .upload-area {
    background-color: #1f2937;
    border-color: #374151;
    color: #f9fafb;
  }

  .upload-area:hover {
    background-color: #111827;
    border-color: #3b82f6;
  }

  .file-preview-area {
    background: linear-gradient(135deg, #1e3a8a, #1e40af);
  }

  .uploaded-file-info {
    background: linear-gradient(135deg, #064e3b, #065f46);
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  .upload-area {
    border-width: 3px;
  }

  .upload-area:hover {
    border-width: 4px;
  }

  .step-icon {
    border: 2px solid currentColor;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

 @keyframes pulse {
        0%, 100% { opacity: 1; }
        50% { opacity: 0.5; }
      }
      .animate-pulse {
        animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
      }

      .timeline-item:last-child .timeline-line {
        display: none !important;
      }

      .timeline-item:hover .timeline-content {
        transform: translateY(-2px);
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
        transition: all 0.3s ease;
      }

      /* Enhanced timeline styling */
      .timeline-dot {
        transition: all 0.3s ease;
      }

      .timeline-dot:hover {
        transform: scale(1.1);
      }

      .timeline-content {
        transition: all 0.3s ease;
        border-left: 3px solid transparent;
      }

      .timeline-item:hover .timeline-content {
        border-left-color: #3b82f6;
        background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
      }

      /* Job header styling */
      .job-header {
        transition: all 0.3s ease;
      }

      .job-header:hover {
        transform: translateY(-1px);
        box-shadow: 0 8px 25px rgba(59, 130, 246, 0.15);
      }

      /* Status badge improvements */
      .timeline-status {
        font-weight: 600;
        letter-spacing: 0.025em;
        transition: all 0.2s ease;
      }

      .timeline-status:hover {
        transform: scale(1.05);
      }

/* Original Styles */
.error {
    color: red;
    font-size: 14px;
}

.loader {
    border: 4px solid #f3f3f3;
    border-top: 4px solid #3498db;
    border-radius: 50%;
    width: 20px;
    height: 20px;
    animation: spin 2s linear infinite;
    cursor: not-allowed;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* Modern Form Styles */
.modern-input {
    width: 100%;
    padding: 0.75rem 1rem;
    border: 1.5px solid #e5e7eb;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    transition: all 0.2s ease;
    background-color: white;
}

.modern-input:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.modern-input:hover {
    border-color: #9ca3af;
}

.error-message {
    color: #dc2626;
    font-size: 0.75rem;
    margin-top: 0.25rem;
    min-height: 1rem;
}

/* Step Indicator Styles */
.step-indicator.active .w-8 {
    background-color: #3b82f6;
    color: white;
}

.step-indicator.active span {
    color: #3b82f6;
    font-weight: 600;
}

.step-indicator.completed .w-8 {
    background-color: #10b981;
    color: white;
}

.step-indicator.completed span {
    color: #10b981;
    font-weight: 600;
}

.step-indicator.completed + .w-16 {
    background-color: #10b981;
}

/* Upload Zone Styles */
.upload-zone {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

.upload-zone:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
}

.upload-zone.dragover {
    border-color: #3b82f6;
    background-color: #eff6ff;
    transform: scale(1.02);
}

.upload-zone.file-selected {
    border-color: #10b981;
    background-color: #f0fdf4;
}

.upload-zone.file-selected .upload-icon svg {
    color: #10b981;
}

/* AI Enhancement Styles */
.ai-powered-badge {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    animation: pulse-glow 2s infinite;
}

@keyframes pulse-glow {
    0%, 100% { box-shadow: 0 2px 8px rgba(59, 130, 246, 0.3); }
    50% { box-shadow: 0 2px 12px rgba(59, 130, 246, 0.5); }
}

/* Progress Animation */
.ai-processing-animation {
    animation: float 3s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-10px); }
}

/* Form Field Animations */
.field-ai-filled {
    background-color: #f0fdf4 !important;
    border-color: #22c55e !important;
    animation: aiFieldGlow 0.8s ease-out;
}

@keyframes aiFieldGlow {
    0% {
        background-color: #dbeafe;
        box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.2);
        transform: scale(1.02);
    }
    50% {
        box-shadow: 0 0 0 8px rgba(59, 130, 246, 0.1);
    }
    100% {
        background-color: #f0fdf4;
        box-shadow: none;
        transform: scale(1);
    }
}

/* Step Content Transitions */
.step-content {
    animation: fadeInSlide 0.5s ease-out;
}

@keyframes fadeInSlide {
    from {
        opacity: 0;
        transform: translateX(20px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Button Hover Effects */
button {
    transition: all 0.2s ease;
}

button:hover {
    transform: translateY(-1px);
}

button:active {
    transform: translateY(0);
}

/* Modal Backdrop Animation */
#uploadModal {
    animation: modalFadeIn 0.3s ease-out;
}

@keyframes modalFadeIn {
    from {
        opacity: 0;
        backdrop-filter: blur(0px);
    }
    to {
        opacity: 1;
        backdrop-filter: blur(4px);
    }
}

#uploadModal > div:last-child {
    animation: modalSlideIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes modalSlideIn {
    from {
        opacity: 0;
        transform: scale(0.9) translateY(-20px);
    }
    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}

/* Progress Bar Animation */
#progress-bar {
    transition: width 0.5s ease-in-out;
}

/* Success Notification */
.success-notification {
    animation: successPulse 0.6s ease-out;
}

@keyframes successPulse {
    0% {
        transform: scale(0.95);
        opacity: 0.8;
    }
    50% {
        transform: scale(1.02);
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

/* Responsive Styles */
@media (max-width: 768px) {
    .ai-powered-badge {
        font-size: 0.75rem;
        padding: 0.25rem 0.5rem;
    }

    #uploadModal > div:first-child {
        max-width: 95%;
    }

    .grid.md\\:grid-cols-2 {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .upload-zone {
        padding: 2rem 1rem;
    }

    .step-indicator {
        flex-direction: column;
        text-align: center;
    }

    .step-indicator span {
        font-size: 0.75rem;
        margin-top: 0.25rem;
    }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
    .upload-zone {
        border-color: #374151;
        background-color: #1f2937;
    }

    .upload-zone:hover {
        border-color: #6b7280;
        background-color: #111827;
    }
}

/* Print styles */
@media print {
    #uploadModal {
        display: none !important;
    }
}

